// Generated by ../../../rebuild.py; one topology per leaf.
use rand::{Rng, rngs::StdRng};

fn pick(rng: &mut StdRng, values: &[f64]) -> f64 {
    values[rng.random_range(0..values.len())]
}

pub fn generate(rng: &mut StdRng) -> String {
    let v = pick(rng, &[1.8, 3.3, 5.0, 9.0, 12.0]);
    let r1 = pick(rng, &[1000.0, 2200.0, 4700.0, 10000.0, 22000.0]);
    let r2 = pick(rng, &[1000.0, 3300.0, 6800.0, 10000.0, 47000.0]);
    let load = r2 * pick(rng, &[2.0, 5.0, 10.0, 20.0]);
    let parallel = r2 * load / (r2 + load);
    let out = v * parallel / (r1 + parallel);
    let resistance = r1 * parallel / (r1 + parallel);
    format!(
        "Loaded resistive voltage divider\n* Ideal voltage source and resistors; values in V and ohms.\n* DC output {out:.5e} V; loaded Thevenin resistance {resistance:.5e} ohm.\nV1 in 0 DC {v:.5e}\nR1 in out {r1:.5e}\nR2 out 0 {r2:.5e}\nRload out 0 {load:.5e}\n.op\n.dc V1 0 {v:.5e} {:.5e}\n.print dc v(in) v(out)\n.end",
        v / 20.0
    )
}

#[cfg(test)]
mod validate;

#[cfg(test)]
mod tests {
    use super::*;
    use rand::SeedableRng;

    #[test]
    fn independent_nodal_analysis_matches_topology() {
        let mut rng = StdRng::seed_from_u64(47);
        for _ in 0..200 {
            validate::verify(&generate(&mut rng), "loaded-divider");
        }
    }
}
